/**
 * The terms and the privacy policy (docs/RAIL-PLAN.md R6.5) are written in
 * `docs/legal/` - English and Croatian, Markdown - and served at `/terms` and
 * `/privacy`. This copies them into `src/lib/legal/texts.generated.ts`, a
 * plain TypeScript module the pages import (no file system at request time,
 * nothing outside `frontend/` for the deployment to trace).
 *
 * Runs before `next dev` and `next build`, like `sites-json.mjs`. The
 * generated file is committed so the type check and the tests see it without
 * a build; the Vitest test `legalPages` fails when it differs from what this
 * script makes from `docs/legal/` - so an edit to a document needs
 * `node scripts/legal-docs.mjs` (or any dev / build) before the commit.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const docs = join(here, "..", "..", "docs", "legal");
const target = join(here, "..", "src", "lib", "legal", "texts.generated.ts");

const DOCUMENTS = [
  ["terms", "TERMS"],
  ["privacy", "PRIVACY"],
];

/** The module's text, from the four documents. */
export function generateLegalModule() {
  const entries = DOCUMENTS.map(([key, file]) => {
    const en = readFileSync(join(docs, `${file}.md`), "utf8");
    const hr = readFileSync(join(docs, `${file}.hr.md`), "utf8");
    return `  ${key}: {\n    en: ${JSON.stringify(en)},\n    hr: ${JSON.stringify(hr)},\n  },`;
  });
  return [
    "// Generated by scripts/legal-docs.mjs from docs/legal/*.md - do not edit by hand.",
    "// Edit the documents, then run `node scripts/legal-docs.mjs` (dev and build run it).",
    "",
    "export const LEGAL_TEXTS = {",
    ...entries,
    "} as const;",
    "",
  ].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(target, generateLegalModule());
  console.log(`legal: ${DOCUMENTS.length * 2} documents written to src/lib/legal/texts.generated.ts`);
}
